"""Overdue fee statements: python3 fees.py INPUT_DIR OUTPUT_FILE"""
import csv
import json
import os
import re
import sys
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal

DAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]


def digits(s):
    d = re.sub(r"\D", "", str(s))
    return int(d) if d else 0


def cents(s):
    return int((Decimal(str(s).strip()) * 100).to_integral_value(rounding="ROUND_HALF_UP"))


def pdate(s):
    return date.fromisoformat(s.strip())


def parse_offset(s):
    s = s.strip()
    m = re.fullmatch(r"([+-])(\d{1,2}):?(\d{2})", s)
    sign = -1 if m.group(1) == "-" else 1
    return timedelta(minutes=sign * (int(m.group(2)) * 60 + int(m.group(3))))


def read_ini(path):
    sections = {}
    cur = None
    with open(path, encoding="utf-8-sig") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            if line.startswith("[") and line.endswith("]"):
                cur = sections.setdefault(line[1:-1].strip(), {})
                continue
            if "=" in line and cur is not None:
                k, v = line.split("=", 1)
                cur[k.strip().lower()] = v.strip()
    return sections


def read_csv(path):
    with open(path, encoding="utf-8-sig", newline="") as f:
        return [{(k or "").strip(): (v or "").strip() for k, v in row.items()}
                for row in csv.DictReader(f)]


def parse_instant(s):
    s = s.strip()
    if s.endswith(("Z", "z")):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc).replace(tzinfo=None)


def main(indir, outfile):
    ini = read_ini(os.path.join(indir, "policy.ini"))
    library = ini["statement"]["library"]
    pstart = pdate(ini["statement"]["period_start"])
    pend = pdate(ini["statement"]["period_end"])

    clock = ini.get("clock", {})
    base_off = parse_offset(clock.get("offset", "+00:00"))
    changes = []
    for part in clock.get("changes", "").split(";"):
        part = part.strip()
        if not part:
            continue
        inst, off = part.split()
        changes.append((parse_instant(inst), parse_offset(off)))
    changes.sort()

    def local_of(utc):
        off = base_off
        for inst, o in changes:
            if utc >= inst:
                off = o
        return utc + off

    items = {}
    cats = {}
    for name, sec in ini.items():
        if name.lower().startswith("item:"):
            tn = name[5:].strip()
            items[tn.lower()] = dict(
                name=tn, loan_days=int(sec["loan_days"]), renewals=int(sec["renewals"]),
                grace=int(sec["grace_days"]), daily=cents(sec["daily"]), loan_cap=cents(sec["loan_cap"]))
        elif name.lower().startswith("category:"):
            cn = name[9:].strip()
            cap = sec.get("statement_cap", "none").strip()
            cats[cn.lower()] = dict(
                name=cn, cap=None if cap.lower() == "none" else cents(cap),
                discount=int(sec.get("discount", "0") or 0),
                exempt={x.strip().lower() for x in sec.get("exempt", "").split(",") if x.strip()})

    branches = read_csv(os.path.join(indir, "branches.csv"))
    branch_ids = [b["branch"] for b in branches]
    bkey = lambda b: b.strip().upper()
    open_days = {bkey(b["branch"]): {w.strip().lower()[:3] for w in b["open_days"].split()} for b in branches}

    cal_branch = {}
    cal_star = {}
    for r in read_csv(os.path.join(indir, "calendar.csv")):
        d = r["date"]
        if ".." in d:
            a, b = d.split("..")
            first, last = pdate(a), pdate(b)
        else:
            first = last = pdate(d)
        status = r["status"].strip().lower()
        target = cal_star if r["branch"].strip() == "*" else cal_branch.setdefault(bkey(r["branch"]), {})
        target_list = target.setdefault("rows", []) if False else None
        rows = (cal_star if r["branch"].strip() == "*" else cal_branch.setdefault(bkey(r["branch"]), {}))
        rows.setdefault("r", []).append((first, last, status))

    def cover(rows, day):
        res = None
        for first, last, st in rows.get("r", []) if rows else []:
            if first <= day <= last:
                res = st
        return res

    open_cache = {}

    def is_open(branch, day):
        k = (bkey(branch), day)
        if k in open_cache:
            return open_cache[k]
        st = cover(cal_branch.get(bkey(branch)), day)
        if st is None:
            st = cover(cal_star, day)
        if st is None:
            res = DAYS[day.weekday()] in open_days.get(bkey(branch), set())
        else:
            res = st == "open"
        open_cache[k] = res
        return res

    def next_open(branch, day):
        for _ in range(3660):
            if is_open(branch, day):
                return day
            day += timedelta(days=1)
        return day

    patrons = {}
    for r in read_csv(os.path.join(indir, "patrons.csv")):
        patrons.setdefault(digits(r["patron"]), []).append((pdate(r["since"]), r["category"], r["patron"]))
    for v in patrons.values():
        v.sort(key=lambda x: x[0])

    def patron_row(pn, day):
        best = None
        for row in patrons.get(pn, []):
            if row[0] <= day:
                best = row
        return best

    waivers = {}
    for r in read_csv(os.path.join(indir, "waivers.csv")):
        if r["status"].strip().lower() != "active":
            continue
        v = r["value"].strip()
        val = "full" if v.lower() == "full" else cents(v)
        waivers.setdefault(digits(r["patron"]), []).append((r["loan"].strip(), val))

    # ---- events
    events = {}
    exdir = os.path.join(indir, "exports")
    for fn in sorted(os.listdir(exdir)):
        path = os.path.join(exdir, fn)
        if not os.path.isfile(path):
            continue
        if fn.endswith(".csv"):
            with open(path, encoding="utf-8-sig", newline="") as f:
                for row in csv.DictReader(f):
                    row = {(k or "").strip(): (v or "").strip() for k, v in row.items()}
                    t = row.get("time", "")
                    row["_local"] = datetime.strptime(t, "%Y-%m-%d %H:%M")
                    events.setdefault(row["event"], row)
        elif fn.endswith(".jsonl"):
            with open(path, encoding="utf-8-sig") as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    o = json.loads(line)
                    row = {k: ("" if v is None else str(v).strip()) for k, v in o.items()}
                    row["_local"] = local_of(parse_instant(row["at"]))
                    events.setdefault(row["event"], row)

    cancelled = set()
    for e in events.values():
        if e.get("type", "").lower() == "void" and e.get("target"):
            cancelled.add(e["target"])

    checkouts = {}
    others = {}
    for eid, e in events.items():
        if eid in cancelled:
            continue
        t = e.get("type", "").lower()
        if t == "checkout":
            checkouts[e["loan"]] = e
        elif t in ("renew", "return"):
            others.setdefault(e["loan"], []).append((e["_local"], t, e))

    # ---- loans
    stmts = {}
    for lid, c in checkouts.items():
        cdate = c["_local"].date()
        if cdate > pend:
            continue
        it = items[c["item_type"].lower()]
        br = c["branch"]
        due = next_open(br, cdate + timedelta(days=it["loan_days"]))
        nren = 0
        ret = None
        for lt, t, e in sorted(others.get(lid, []), key=lambda x: x[0]):
            d = lt.date()
            if t == "renew":
                if d <= due and nren < it["renewals"] and d <= pend:
                    nren += 1
                    due = next_open(br, d + timedelta(days=it["loan_days"]))
            else:
                ret = d - timedelta(days=1) if e.get("via", "").lower() == "dropbox" else d
                break
        if ret is not None and ret > pend:
            ret = None
        if ret is not None and ret < pstart:
            continue
        end = ret if ret is not None else pend
        overdue = 0
        d = due + timedelta(days=1)
        while d <= end:
            if is_open(br, d):
                overdue += 1
            d += timedelta(days=1)
        if overdue == 0:
            continue
        pn = digits(c["patron"])
        cat = cats[patron_row(pn, cdate)[1].lower()]
        charged = overdue if overdue > it["grace"] else 0
        fee = charged * it["daily"]
        if it["name"].lower() in cat["exempt"]:
            fee = 0
        fee = min(fee, it["loan_cap"])
        assessed = (fee * (100 - cat["discount"]) + 50) // 100
        waived = 0
        full = False
        tot = 0
        for wl, val in waivers.get(pn, []):
            if wl == "*" or wl == lid:
                if val == "full":
                    full = True
                else:
                    tot += val
        waived = assessed if full else min(tot, assessed)
        stmts.setdefault(pn, []).append(dict(
            loan=lid, item=c.get("item", ""), item_type=it["name"], branch=br,
            checkout=cdate.isoformat(), due=due.isoformat(),
            returned=ret.isoformat() if ret is not None else None,
            overdue_days=overdue, charged_days=charged, assessed=assessed, waived=waived,
            capped=0, billed=0, _net=assessed - waived))

    out_statements = []
    for pn in sorted(stmts):
        loans = stmts[pn]
        loans.sort(key=lambda x: (x["due"], x["loan"]))
        row = patron_row(pn, pend)
        cat = cats[row[1].lower()]
        net = sum(x["_net"] for x in loans)
        excess = net - cat["cap"] if cat["cap"] is not None and net > cat["cap"] else 0
        for x in sorted(loans, key=lambda x: (x["due"], x["loan"]), reverse=True):
            give = min(excess, x["_net"])
            x["capped"] = give
            excess -= give
        for x in loans:
            x["billed"] = x["_net"] - x["capped"]
            del x["_net"]
        st = dict(patron=row[2], category=cat["name"], loans=loans)
        for k in ("assessed", "waived", "capped", "billed"):
            st[k] = sum(x[k] for x in loans)
        out_statements.append(st)

    summary = []
    for b in branch_ids:
        ls = [x for s in out_statements for x in s["loans"] if bkey(x["branch"]) == bkey(b)]
        summary.append(dict(branch=b, loans=len(ls), charged_days=sum(x["charged_days"] for x in ls),
                            **{k: sum(x[k] for x in ls) for k in ("assessed", "waived", "capped", "billed")}))
    for s in out_statements:
        for x in s["loans"]:
            for b in branch_ids:
                if bkey(b) == bkey(x["branch"]):
                    x["branch"] = b

    result = dict(library=library, period=dict(start=pstart.isoformat(), end=pend.isoformat()),
                  statements=out_statements, branches=summary)
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
